<?php
namespace App\Observers;
use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;
class AuditObserver { public function created(Model $model):void{$this->write('created',$model,null,$model->getAttributes());}public function updated(Model $model):void{$this->write('updated',$model,$model->getOriginal(),$model->getChanges());}public function deleted(Model $model):void{$this->write('deleted',$model,$model->getOriginal(),null);}private function write(string $action,Model $model,?array $old,?array $new):void{DB::table('audit_logs')->insert(['user_id'=>Auth::id(),'action'=>$action,'entity_type'=>$model::class,'entity_id'=>$model->getKey(),'ip_address'=>request()?->ip(),'user_agent'=>request()?->userAgent(),'old_values'=>$old?json_encode($this->safe($old)):null,'new_values'=>$new?json_encode($this->safe($new)):null,'created_at'=>now()]);}private function safe(array $v):array{unset($v['password'],$v['remember_token']);return $v;} }
